#!/usr/local/bin/php -q<?phpinclude("connect.inc.php");include("userfunctions.inc.php");$fp = fopen("turntime.txt","w");fwrite($fp,time());fclose($fp);function ProcessIncome(){	$sql = "SELECT PlayerID FROM players";	$res = mysql_query($sql);	while($row = mysql_fetch_object($res)){		$income = GetUserIncome($row->PlayerID);		AddResources($row->PlayerID,1,$income->Metal);	//	echo "Adding ".$income["Metal"]." Metal to user: ".$row->PlayerID."\n";		AddResources($row->PlayerID,2,$income->Mineral);	//	echo "Adding ".$income["Mineral"]." Mineral to user: ".$row->PlayerID."\n";		AddResources($row->PlayerID,3,$income->Astrium);	//	echo "Adding ".$income["Astrium"]." Astrium to user: ".$row->PlayerID."\n";	}}ProcessIncome();?>